package com.example.observatory;
import java.net.URI;import java.net.http.*;import java.time.Duration;
public final class AlertClient{private final String base;private final HttpClient h=HttpClient.newBuilder().connectTimeout(Duration.ofSeconds(5)).build();public AlertClient(String b){base=b.replaceAll("/$","");}public String score(Window w)throws Exception{var q=HttpRequest.newBuilder(URI.create(base+"/v1/score")).timeout(Duration.ofSeconds(10)).header("Content-Type","application/json").POST(HttpRequest.BodyPublishers.ofString(w.json())).build();var r=h.send(q,HttpResponse.BodyHandlers.ofString());if(r.statusCode()/100!=2)throw new IllegalStateException(r.body());return r.body();}public static void main(String[]a)throws Exception{System.out.println(new AlertClient(a.length>0?a[0]:"http://127.0.0.1:8000").score(new Window("W-DEMO",420,.1,120,.9)));}public record Window(String id,double latency,double errors,double rps,double cpu){String json(){return String.format("{\"window_id\":\"%s\",\"p95_latency_ms\":%.1f,\"error_rate\":%.3f,\"requests_per_second\":%.1f,\"cpu_saturation\":%.3f}",id,latency,errors,rps,cpu);}}}
